arguments.command:
mkdir -p /app/w && cat > /app/w/p.py <<'E'
import numpy as np,sys
from scipy.stats import t
loc={'bureau':[835,805,772,765,725,700],'income':[782,695,655,605,600,640],'bank':[790,745,670,680,625,610]}
sc={'bureau':35,'income':40,'bank':30}
edges=[-1e9,560,630,690,750,820,1e9]
PD=np.array([.02,.05,.12,.3,.6,.9]);ev=(1-PD)*1000-PD*16000
def lik(c,b):
    return np.array([t.cdf((edges[b+1]-m)/sc[c],3)-t.cdf((edges[b]-m)/sc[c],3) for m in loc[c]])
prior=np.array(eval(sys.argv[1]));obs=sys.argv[2:]
post=prior.copy()
for o in obs:
    c,b=o.split(':');post=post*lik(c,int(b))
post/=post.sum()
print(post.round(3),'EV approve',round(post@ev))
# value of one more check each kind
for c in sc:
    v=0
    for b in range(6):
        l=lik(c,b);pb=(post*l).sum();pp=post*l/pb;v+=pb*max(0,pp@ev)
    print(c,'gain',round(v-max(0,post@ev)))
E
cd /app/w; python3 p.py "[.25,.16,.09,.06,.26,.18]"

